# Paginate text messages manually
text_page = 0
while True:
    page_msgs = apis.phone.search_text_messages(access_token=token, phone_number=spam_number, page_index=text_page)
    if not page_msgs:
        break
    for msg in page_msgs:
        apis.phone.delete_text_message(access_token=token, text_message_id=msg['text_message_id'])
    text_page += 1

